pub inline fn sumF16(v: @Vector(16, f32)) f32 {
    const a: [16]f32 = @bitCast(v);
    const lo: @Vector(8, f32) = @bitCast(a[0..8].*);
    const hi: @Vector(8, f32) = @bitCast(a[8..16].*);
    return @reduce(.Add, lo) + @reduce(.Add, hi);
